using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using QuietDread;
public static class TerrainChecks {
 public static void Run(string root){var d=Content.Load();var lines=new List<string>();Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("TERRAIN CHECK FAILED: "+name);lines.Add("PASS "+name);};
 foreach(var size in new[]{new Vector2Int(24,16),new Vector2Int(32,22),new Vector2Int(40,28)})foreach(var edge in new[]{"west","east","north","south"}){var b=Battle.Create(d,"vermin",d.F("vermin").defaults.ToList(),"vault");b.ConfigureField(size.x,size.y,edge,"wetlands");check(b.terrain.Length==size.x*size.y,"terrain dimensions "+size+" / "+edge);check(b.units.All(u=>b.InDeployment(u.team,u.x,u.y)&&b.Passable(b.P(u),u.x,u.y)),"legal opposing deployments "+size+" / "+edge);check(b.units.Select(u=>u.y*b.width+u.x).Distinct().Count()==b.units.Count,"unique deployment positions "+size+" / "+edge);var walker=b.Living(0).First();var reachable=b.Reach(walker,size.x*size.y);check(b.Objectives.All(r=>reachable.ContainsKey(r.y*b.width+r.x)),"infantry can reach all relays "+size+" / "+edge);var restored=JsonUtility.FromJson<Battle>(JsonUtility.ToJson(b));restored.data=d;check(restored.width==size.x&&restored.height==size.y&&restored.deploymentSide==edge&&restored.fieldConfigured,"field save roundtrip "+size+" / "+edge);}
 var test=Battle.Create(d,"vermin",new List<string>{"marshal"},"compact",new List<string>{"captain"});test.ConfigureField(24,16,"north","woodland");test.terrain=new int[24*16];var a=test.units[0];var target=test.units[1];a.x=5;a.y=5;target.x=10;target.y=5;test.terrain[5*24+6]=5;check(!test.Reach(a,1).ContainsKey(5*24+6),"ground cannot enter water");var flyer=d.P("argent_4");var amphib=d.P("pelagic_0");check(flyer.flying&&amphib.amphibious,"explicit movement traits loaded");a.type=flyer.id;check(test.Reach(a,1).ContainsKey(5*24+6),"flying enters water");a.type=amphib.id;check(test.Reach(a,1).ContainsKey(5*24+6),"amphibious enters water");test.terrain[5*24+6]=6;a.type="marshal";check(!test.Reach(a,1).ContainsKey(5*24+6)&&test.Reach(a,2)[5*24+6]==2,"marsh consumes two movement");a.type=amphib.id;check(test.Reach(a,1)[5*24+6]==1,"amphibious ignores marsh penalty");a.type="marshal";test.terrain[5*24+6]=4;check(test.MoveCost(test.P(a),6,5)==2,"woodland slows ordinary infantry");test.terrain[5*24+6]=9;check(!test.LOS(5,5,10,5),"buildings block line of sight");a.type=flyer.id;check(!test.Reach(a,2).ContainsKey(5*24+6)&&test.Reach(a,2).ContainsKey(5*24+7),"flying crosses buildings without landing inside");a.type="marshal";test.terrain=new int[24*16];test.terrain[5*24+9]=7;check(test.Cover(a,target)==25&&test.LOS(5,5,10,5),"low wall provides directional cover without blocking shots");test.terrain[5*24+9]=8;check(test.Cover(a,target)==25&&!test.LOS(5,5,10,5),"rocks provide cover and block sight");test.terrain[5*24+9]=1;check(test.Cover(a,target)==25,"ruins provide cover");test.terrain[5*24+9]=0;test.terrain[5*24+10]=4;check(test.Cover(a,target)==20,"woodland provides cover");
 foreach(var size in new[]{new Vector2Int(24,16),new Vector2Int(32,22),new Vector2Int(40,28)}){var b=Battle.Create(d,"argent",d.F("argent").defaults.Take(5).ToList(),"pelagic",d.F("pelagic").defaults.Take(5).ToList(),52);b.ConfigureField(size.x,size.y,"south","wetlands");b.Begin();int steps=0;while(!b.finished&&steps++<6000)b.AI();check(b.finished,"AI finishes terrain battle "+size);check(b.units.All(u=>!u.Alive||b.Passable(b.P(u),u.x,u.y)),"AI respects terrain restrictions "+size);}
 lines.Insert(0,lines.Count+" terrain, deployment, pathfinding and serialization checks passed.");File.WriteAllLines(Path.Combine(root,"Documentation/TERRAIN-TEST-RESULTS.txt"),lines);
 }
}
